import{_ as t,g as e,e as n,a4 as c}from"./chunks/framework.CEYJDsBW.js";const h=JSON.parse('{"title":"AnvilEvent","description":"","frontmatter":{},"headers":[],"relativePath":"anvilcraft/26.1/events/anvil-event.md","filePath":"anvilcraft/26.1/events/anvil-event.md"}'),r={name:"anvilcraft/26.1/events/anvil-event.md"};function i(l,a,o,d,v,f){return e(),n("div",null,[...a[0]||(a[0]=[c('<h1 id="anvilevent" tabindex="-1">AnvilEvent <a class="header-anchor" href="#anvilevent" aria-label="Permalink to &quot;AnvilEvent&quot;">​</a></h1><p>想在落点执行一次操作，应先区分整座巨砧和落点方块。普通 <code>OnLand</code> 提供铁砧落点，承压方块在 <code>getPos().below()</code>。巨砧落成后先发一次 <code>GiantOnLand</code>，再在 3 × 3 底面逐格发九次 <code>OnLand</code>。整座结构只结算一次时订阅前者。铁砧锤也有用临时实体发布 <code>OnLand</code> 的路径。</p><p>普通下落铁砧的发布者会读取 <code>OnLand.setAnvilDamage(true)</code> 对应的标志，按铁砧损伤流程更新落点。巨砧的九次通知没有这一步回读。<code>CollisionBlock</code> 在移动结束后报告碰撞，其 <code>speed</code> 是碰撞前移动向量的长度。取消可阻止后续内置碰撞合成监听器，已执行的实体移动无法由此撤销。<code>HurtEntity</code> 提供目标和伤害数值，字段只读。<a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/event/FallingBlockCollisionEventListener.java" target="_blank" rel="noreferrer">碰撞处理</a> · <a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/workstation/GiantAnvilBlock.java" target="_blank" rel="noreferrer">巨砧落成</a></p><table tabindex="0"><thead><tr><th>事件类型</th><th>创建位置</th></tr></thead><tbody><tr><td><code>AnvilEvent</code></td><td>此提交中未检出以该名称直接构造的调用点</td></tr><tr><td><code>AnvilEvent.OnLand</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/workstation/GiantAnvilBlock.java#L292" target="_blank" rel="noreferrer"><code>GiantAnvilBlock:292</code></a>、<a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/entity/FallingSpectralBlockEntity.java#L105" target="_blank" rel="noreferrer"><code>FallingSpectralBlockEntity:105</code></a>、<a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/item/tool/AnvilHammerItem.java#L197" target="_blank" rel="noreferrer"><code>AnvilHammerItem:197</code></a>、<a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/mixin/FallingBlockEntityMixin.java#L420" target="_blank" rel="noreferrer"><code>FallingBlockEntityMixin:420</code></a></td></tr><tr><td><code>AnvilEvent.CollisionBlock</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/mixin/EntityMixin.java#L308" target="_blank" rel="noreferrer"><code>EntityMixin:308</code></a></td></tr><tr><td><code>AnvilEvent.GiantOnLand</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/workstation/GiantAnvilBlock.java#L288" target="_blank" rel="noreferrer"><code>GiantAnvilBlock:288</code></a></td></tr><tr><td><code>AnvilEvent.HurtEntity</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/entity/FallingSpectralBlockEntity.java#L271" target="_blank" rel="noreferrer"><code>FallingSpectralBlockEntity:271</code></a>、<a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/mixin/FallingBlockEntityMixin.java#L461" target="_blank" rel="noreferrer"><code>FallingBlockEntityMixin:461</code></a></td></tr></tbody></table>',4)])])}const s=t(r,[["render",i]]);export{h as __pageData,s as default};
